![图](原文/期中/assets/期中/2012期中-带答案/page-06.png)

> 上图为本页内容（汇编代码清单 + 红色印刷的 C 语言参考代码）。

```asm
	.globl mystery_sort	# exports the symbol so other .c files
				# can call the function

mystery_sort:
	jmp	loop1_check

loop1:
	xor	%rdx, %rdx
	mov	%rsi, %rcx
	jmp	loop2_check

loop2:
	mov	(%rdi, %rcx, 8), %rax
	cmp	%rax, (%rdi, %rdx, 8)
	jg	loop2_check
	mov	%rcx, %rdx

loop2_check:
	dec	%rcx
	test	%rcx, %rcx
	jnz	loop2

	dec	%rsi
	mov	(%rdi, %rsi, 8), %rax
	mov	(%rdi, %rdx, 8), %rcx
	mov	%rcx, (%rdi, %rsi, 8)
	mov	%rax, (%rdi, %rdx, 8)

loop1_check:
	test	%rsi, %rsi
	jnz	loop1

	ret
```

**答案（原卷红色印刷）：**

```c
void mystery_sort (long* array, long len)
{
    long a, b, tmp;
    while(len>0)
    {
        a = 0;
        for(b=len-1; b>0; b--)
        {
            if(array[b]>array[a])
            {
                a=b;
            }
        }
        len--;
        tmp = array[len];
        array[len] = array[a];
        array[a] = tmp;
    }
}
```

